  # Subcomponent stock_to_cof of type MultibodyComponents.FixedTranslation
  stock_to_cof_overrides = __pop_subcomponent_overrides!(__overrides, "stock_to_cof")
  push!(__systems, @named stock_to_cof = MultibodyComponents.FixedTranslation(; r=CenterOfForces, render=false, stock_to_cof_overrides...))
  # Subcomponent cof_hull of type MultibodyComponents.FixedTranslation
  cof_hull_overrides = __pop_subcomponent_overrides!(__overrides, "cof_hull")
  push!(__systems, @named cof_hull = MultibodyComponents.FixedTranslation(; r=CenterOfForces, render=false, cof_hull_overrides...))
  # Subcomponent apparent of type DyadShip.Ship6DOF.ApparentSpeedXY
  apparent_overrides = __pop_subcomponent_overrides!(__overrides, "apparent")
  push!(__systems, @named apparent = DyadShip.Ship6DOF.ApparentSpeedXY(; apparent_overrides...))
  # Subcomponent force of type MultibodyComponents.WorldForce
  force_overrides = __pop_subcomponent_overrides!(__overrides, "force")
  push!(__systems, @named force = MultibodyComponents.WorldForce(; resolve_in_frame=MultibodyComponents.ResolveInFrame.FrameB(), render=false, force_overrides...))
  # Subcomponent torque of type MultibodyComponents.WorldTorque
  torque_overrides = __pop_subcomponent_overrides!(__overrides, "torque")
  push!(__systems, @named torque = MultibodyComponents.WorldTorque(; resolve_in_frame=MultibodyComponents.ResolveInFrame.FrameB(), torque_overrides...))
  # Subcomponent Cl_table of type BlockComponents.Tables.InterpolatedTable
  Cl_table_overrides = __pop_subcomponent_overrides!(__overrides, "Cl_table")
  push!(__systems, @named Cl_table = BlockComponents.Tables.InterpolatedTable(; axis1=Cl_data["angle_deg"], axis2=Cl_data["Re"], data=Cl_data["Cl"], interpolation_dim1=BlockComponents.Tables.InterpolationDimension.LinearInterpolationDimension(), interpolation_dim2=BlockComponents.Tables.InterpolationDimension.LinearInterpolationDimension(), Cl_table_overrides...))
  # Subcomponent Cd_table of type BlockComponents.Tables.InterpolatedTable
  Cd_table_overrides = __pop_subcomponent_overrides!(__overrides, "Cd_table")
  push!(__systems, @named Cd_table = BlockComponents.Tables.InterpolatedTable(; axis1=Cd_data["angle_deg"], axis2=Cd_data["Re"], data=Cd_data["Cd"], interpolation_dim1=BlockComponents.Tables.InterpolationDimension.LinearInterpolationDimension(), interpolation_dim2=BlockComponents.Tables.InterpolationDimension.LinearInterpolationDimension(), Cd_table_overrides...))
  # Subcomponent Cm_table of type BlockComponents.Tables.InterpolatedTable
  Cm_table_overrides = __pop_subcomponent_overrides!(__overrides, "Cm_table")
  push!(__systems, @named Cm_table = BlockComponents.Tables.InterpolatedTable(; axis1=Cm_data["angle_deg"], axis2=Cm_data["Re"], data=Cm_data["Cm"], interpolation_dim1=BlockComponents.Tables.InterpolationDimension.LinearInterpolationDimension(), interpolation_dim2=BlockComponents.Tables.InterpolationDimension.LinearInterpolationDimension(), Cm_table_overrides...))

  ### Check there are no unmatched overrides
  isempty(__overrides) || throw(ArgumentError("overrides: [$(join(keys(__overrides), ", "))] don't match names found in model. These names may exist in the model but could have been conditionally excluded."))

  ### Guesses
  isnothing(__ovr_Wx__guess) || (__guesses[Wx] = __ovr_Wx__guess)
  isnothing(__ovr_Wy__guess) || (__guesses[Wy] = __ovr_Wy__guess)
  isnothing(__ovr_WaterSpeed__guess) || (__guesses[WaterSpeed] = __ovr_WaterSpeed__guess)
  isnothing(__ovr_Re__guess) || (__guesses[Re] = __ovr_Re__guess)
  isnothing(__ovr_Beta_R__guess) || (__guesses[Beta_R] = __ovr_Beta_R__guess)
  isnothing(__ovr_Gamma_R__guess) || (__guesses[Gamma_R] = __ovr_Gamma_R__guess)
  isnothing(__ovr_delta__guess) || (__guesses[delta] = __ovr_delta__guess)
  isnothing(__ovr_F_blade__guess) || (__guesses[F_blade] = __ovr_F_blade__guess)
  isnothing(__ovr_alpha_deg__guess) || (__guesses[alpha_deg] = __ovr_alpha_deg__guess)
  isnothing(__ovr_Cl__guess) || (__guesses[Cl] = __ovr_Cl__guess)
  isnothing(__ovr_Cd__guess) || (__guesses[Cd] = __ovr_Cd__guess)
  isnothing(__ovr_Cm__guess) || (__guesses[Cm] = __ovr_Cm__guess)
  isnothing(__ovr_Lambda__guess) || (__guesses[Lambda] = __ovr_Lambda__guess)
  isnothing(__ovr_qS__guess) || (__guesses[qS] = __ovr_qS__guess)
  isnothing(__ovr_e_d__guess) || (__guesses[e_d] = __ovr_e_d__guess)
  isnothing(__ovr_sgn__guess) || (__guesses[sgn] = __ovr_sgn__guess)

  ### Initialization Equations

  ### Assertions
  __assertions = []

  ### Equations
  push!(__eqs, drive.phi_ref ~ rate_limiter.y * π / 180)
  push!(__eqs, delta ~ servo.phi)
  push!(__eqs, Rudder_position ~ delta * 180 / π)
  push!(__eqs, apparent.WorldSpeed_x ~ Current_x)
  push!(__eqs, apparent.WorldSpeed_y ~ Current_y)
  push!(__eqs, Wx ~ ifelse(Propeller_flow_diameter >= s, -Propeller_speed, -(Propeller_speed * Propeller_flow_diameter + apparent.SpeedLocal_x * (1 - Wake_Fraction) * (s - Propeller_flow_diameter)) / s))
  push!(__eqs, Wy ~ -apparent.SpeedLocal_y)
  push!(__eqs, WaterSpeed ~ sqrt(Wx ^ 2 + Wy ^ 2 + 0.000001))
  push!(__eqs, Re ~ WaterSpeed * C / SeaKViscosity)
  push!(__eqs, Beta_R ~ atan(Wy, -Wx))
  push!(__eqs, Gamma_R ~ ifelse(Beta_R > 0, Gamma_R_Neg, Gamma_R_Pos))
  push!(__eqs, Alpha_eff ~ delta - Gamma_R * Beta_R)
  push!(__eqs, sgn ~ Alpha_eff / sqrt(Alpha_eff ^ 2 + alpha_eps ^ 2))
  push!(__eqs, alpha_deg ~ clamp(abs(Alpha_eff) * 180 / π, 0, 180))
  push!(__eqs, Cl_table.u1 ~ alpha_deg)
  push!(__eqs, Cl_table.u2 ~ clamp(Re, Re_min, Re_max))
  push!(__eqs, Cd_table.u1 ~ alpha_deg)
  push!(__eqs, Cd_table.u2 ~ clamp(Re, Re_min, Re_max))
  push!(__eqs, Cm_table.u1 ~ alpha_deg)
  push!(__eqs, Cm_table.u2 ~ clamp(Re, Re_cm_min, Re_cm_max))
  push!(__eqs, Cl ~ Cl_table.y * Cn_Asp_Correction)
  push!(__eqs, Cd ~ Cd_table.y * Cn_Asp_Correction)
  push!(__eqs, Cm ~ Cm_table.y)
  push!(__eqs, Lambda ~ max(abs(apparent.SpeedLocal_x * (1 - Wake_Fraction)) / (abs(Wx) + 0.000001), 0.001) ^ (2 * (2 / (2 + (0.886 * (Propeller_flow_diameter / 2) / C))) ^ 8))
  push!(__eqs, qS ~ 0.5 * SeaDensity * Surf * WaterSpeed ^ 2)
  push!(__eqs, Drag ~ Cd * qS)
  push!(__eqs, Lift ~ Cl * Lambda * qS)
  push!(__eqs, Moment ~ Cm * qS * C)
  push!(__eqs, e_d ~ [Wx, Wy] / WaterSpeed)
  push!(__eqs, Force_X ~ Drag * e_d[1] - Lift * sgn * e_d[2])
  push!(__eqs, Force_Y ~ (Drag * e_d[2] + Lift * sgn * e_d[1]) * (1 + a_h))
  push!(__eqs, F_blade ~ [cos(delta) * Force_X + sin(delta) * Force_Y, -sin(delta) * Force_X + cos(delta) * Force_Y])
  push!(__eqs, force.force_x ~ F_blade[1])
  push!(__eqs, force.force_y ~ F_blade[2])
  push!(__eqs, force.force_z ~ 0)
  push!(__eqs, torque.torque_x ~ 0)
  push!(__eqs, torque.torque_y ~ 0)
  push!(__eqs, torque.torque_z ~ Moment * sgn)
  push!(__eqs, connect(Rudder_Order, angle_limiter.u))
  push!(__eqs, connect(angle_limiter.y, rate_limiter.u))
  push!(__eqs, connect(drive.spline, servo.axis))
  push!(__eqs, connect(drive.support, servo.support))
  push!(__eqs, connect(frame_a, servo.frame_a, cof_hull.frame_a))
  push!(__eqs, connect(servo.frame_b, stock_to_cof.frame_a))
  push!(__eqs, connect(stock_to_cof.frame_b, force.frame_b, torque.frame_b))
  push!(__eqs, connect(cof_hull.frame_b, apparent.frame_a))

  # Return completely constructed System
  return System(__eqs, t, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export Rudder
